========================= */

function Sidebar() {
  return (
    <aside className="sidebar">

      {/* LOGO */}
      <div className="logo">
        <div className="logo-circle">
          👨‍👩‍👧
        </div>

        <div className="logo-text">
          <strong>GROWW</strong>
          <strong>SMM</strong>
        </div>
      </div>

      {/* NAVIGATION */}
      <nav className="navigation">

        {menuItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            end={item.path === "/"}
            className={({ isActive }) =>
              `nav-item ${isActive ? "active" : ""}`
            }
          >
            <span className="nav-icon">
              {item.icon}
            </span>

            <span className="nav-label">
              {item.name}
            </span>
          </NavLink>
        ))}

      </nav>
    </aside>
  );
}

